const r = await tools.exec_command({cmd:"node <<'NODE'
const fs = require('fs');
const text = fs.readFileSync('specs/001-bookmark-manager/tasks.md', 'utf8');
const lines = text.split('\n').filter(line => line.startsWith('- [ ]'));
const pattern = /^- \[ \] T(\d{3})(?: \[P\])?(?: \[US[1-4]\])? .+`[^`]+`/;
const bad = lines.filter(line => !pattern.test(line));
if (bad.length) {
  console.error('Invalid task lines:\n' + bad.join('\n'));
  process.exit(1);
}
const ids = lines.map(line => Number(line.match(/^\- \[ \] T(\d{3})/)[1]));
ids.forEach((id, index) => {
  if (id !== index + 1) throw new Error(`Expected T${String(index + 1).padStart(3,'0')}, got T${String(id).padStart(3,'0')}`);
});
const counts = {setup: 0, foundation: 0, US1: 0, US2: 0, US3: 0, US4: 0, polish: 0, parallel: 0};
for (const line of lines) {
  const story = line.match(/\[(US[1-4])\]/)?.[1];
  if (story) counts[story]++;
  if (line.includes('[P]')) counts.parallel++;
  const id = Number(line.match(/T(\d{3})/)[1]);
  if (id <= 6) counts.setup++;
  else if (id <= 17) counts.foundation++;
  else if (id >= 66) counts.polish++;
}
console.log(JSON.stringify({total: lines.length, ...counts}, null, 2));
NODE
