import { Component, type ErrorInfo, type ReactNode } from 'react';

class ErrorBoundary extends Component<{children: ReactNode},{failed:boolean}> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error(error, info); }
  render() { return this.state.failed ? <main className="shell"><h1>Bookmark Garden</h1><p role="alert">The app could not load. Refresh to try again.</p></main> : this.props.children; }
}

export function App() {
  return <ErrorBoundary><main className="shell" data-harness-ready="true"><header className="masthead"><span className="eyebrow">Your quiet corner of the web</span><h1>Bookmark Garden</h1><p>Save what matters. Find it when you need it.</p></header><section className="empty"><span aria-hidden="true">✦</span><h2>Your garden is ready</h2><p>Add a first link to start growing your collection.</p></section></main></ErrorBoundary>;
}

