export type TokenType='term'|'phrase'|'tag'|'and'|'or'|'not'|'lparen'|'rparen'|'eof';
export type Token={type:TokenType;value:string;start:number;end:number};
export class LexError extends Error{constructor(message:string,public start:number,public end:number){super(message)}}
function quoted(source:string,start:number):{value:string;end:number}{let value='';let index=start+1;for(;index<source.length;index++){const char=source[index]!;if(char==='"')return{value,end:index+1};if(char==='\\'){const next=source[index+1];if(next==='"'||next==='\\'){value+=next;index++;continue}}value+=char}throw new LexError(`Missing closing quote starting at character ${start}`,start,source.length)}
export function lex(source:string):Token[]{const tokens:Token[]=[];let i=0;while(i<source.length){if(/\s/u.test(source[i]!)){i++;continue}const start=i;const char=source[i]!;if(char==='('){tokens.push({type:'lparen',value:char,start,end:++i});continue}if(char===')'){tokens.push({type:'rparen',value:char,start,end:++i});continue}if(char==='"'){const result=quoted(source,i);if(!result.value)throw new LexError('Quoted phrases cannot be empty.',start,result.end);tokens.push({type:'phrase',value:result.value,start,end:result.end});i=result.end;continue}if(char==='#'){i++;if(source[i]==='"'){const result=quoted(source,i);if(!result.value)throw new LexError('Add a tag name after “#”.',start,result.end);tokens.push({type:'tag',value:result.value,start,end:result.end});i=result.end;continue}const tagStart=i;while(i<source.length&&!/[\s()"]/.test(source[i]!))i++;if(i===tagStart)throw new LexError('Add a tag name after “#”.',start,i);tokens.push({type:'tag',value:source.slice(tagStart,i),start,end:i});continue}while(i<source.length&&!/[\s()"]/.test(source[i]!))i++;const value=source.slice(start,i);const keyword=value.toUpperCase();tokens.push({type:keyword==='AND'?'and':keyword==='OR'?'or':keyword==='NOT'?'not':'term',value,start,end:i})}tokens.push({type:'eof',value:'',start:source.length,end:source.length});return tokens}

