import{useEffect,useId,useState,type KeyboardEvent}from'react';import type{Tag}from'../../../shared/contracts/types.js';import{suggestTags}from'../../services/tags.js';
const identity=(value:string)=>value.normalize('NFKC').toLocaleLowerCase().trim().replace(/\s+/g,' ');
export function TagCombobox({tags,onChange}:{tags:string[];onChange:(tags:string[])=>void}){const[input,setInput]=useState('');const[suggestions,setSuggestions]=useState<Tag[]>([]);const[active,setActive]=useState(-1);const listId=useId();useEffect(()=>{if(!input.trim()){setSuggestions([]);return}const controller=new AbortController();const timer=setTimeout(()=>void suggestTags(input,tags,controller.signal).then(result=>{setSuggestions(result.items);setActive(-1)}).catch(()=>{}),180);return()=>{clearTimeout(timer);controller.abort()}},[input,tags]);function add(value:string){const clean=value.trim().replace(/\s+/g,' ');if(clean&&!tags.some(tag=>identity(tag)===identity(clean)))onChange([...tags,clean]);setInput('');setSuggestions([]);setActive(-1)}function keys(event:KeyboardEvent<HTMLInputElement>){if(event.key==='ArrowDown'&&suggestions.length){event.preventDefault();setActive(value=>Math.min(value+1,suggestions.length-1))}else if(event.key==='ArrowUp'&&suggestions.length){event.preventDefault();setActive(value=>Math.max(value-1,0))}else if(event.key==='Enter'){event.preventDefault();add(active>=0?suggestions[active]!.name:input)}else if(event.key==='Escape'){setSuggestions([]);setActive(-1)}}return <div className="tag-field"><label htmlFor={`${listId}-input`}>Tags</label><div className="tag-entry">{tags.map(tag=><span className="tag selected" key={identity(tag)}>#{tag}<button type="button" aria-label={`Remove ${tag}`} onClick={()=>onChange(tags.filter(item=>identity(item)!==identity(tag)))}>×</button></span>)}<input id={`${listId}-input`} role="combobox" aria-autocomplete="list" aria-expanded={Boolean(suggestions.length)} aria-controls={listId} aria-activedescendant={active>=0?`${listId}-${active}`:undefined} value={input} placeholder={tags.length?'Add another…':'design, research'} onChange={e=>setInput(e.target.value)} onKeyDown={keys}/></div>{suggestions.length>0&&<ul id={listId} role="listbox" className="suggestions">{suggestions.map((tag,index)=><li id={`${listId}-${index}`} role="option" aria-selected={active===index} key={tag.id} onMouseDown={event=>{event.preventDefault();add(tag.name)}}>#{tag.name}</li>)}</ul>}<span className="sr-only" aria-live="polite">{suggestions.length?`${suggestions.length} tag suggestions available`:''}</span></div>}

