import { Component, useCallback, useEffect, useRef, useState, type ErrorInfo, type ReactNode } from 'react';
import type { Bookmark } from '../../shared/contracts/types.js';
import { listBookmarks } from '../services/bookmarks.js';
import { BookmarkForm } from '../features/bookmarks/BookmarkForm.js';
import { BookmarkList } from '../features/bookmarks/BookmarkList.js';
import { SearchControls } from '../features/search/SearchControls.js';
import { useCollectionSearch } from '../features/search/useCollectionSearch.js';

class ErrorBoundary extends Component<{children:ReactNode},{failed:boolean}>{state={failed:false};static getDerivedStateFromError(){return{failed:true}}componentDidCatch(error:Error,info:ErrorInfo){console.error(error,info)}render(){return this.state.failed?<main className="shell"><h1>Bookmark Garden</h1><p role="alert">The app could not load. Refresh to try again.</p></main>:this.props.children}}
export function App(){const[items,setItems]=useState<Bookmark[]>([]);const[loading,setLoading]=useState(true);const[open,setOpen]=useState(false);const[message,setMessage]=useState('');const[searchError,setSearchError]=useState('');const{state,setState,reset}=useCollectionSearch();const first=useRef(true);const load=useCallback(async(signal?:AbortSignal)=>{try{setSearchError('');setItems((await listBookmarks({query:state.query,tags:state.tags,favorite:state.favorite,unread:state.unread},signal)).items)}catch(error){if((error as Error).name!=='AbortError')setSearchError((error as Error).message)}finally{setLoading(false)}},[state]);useEffect(()=>{const controller=new AbortController();const delay=first.current?0:250;first.current=false;const timer=setTimeout(()=>void load(controller.signal),delay);return()=>{clearTimeout(timer);controller.abort()}},[load]);const noMatches=!loading&&!items.length&&Boolean(state.query||state.tags.length||state.favorite||state.unread);return <ErrorBoundary><main className="shell" {...(!loading?{'data-harness-ready':'true'}:{})}><header className="masthead"><div><span className="eyebrow">Your quiet corner of the web</span><h1>Bookmark Garden</h1><p>Save what matters. Find it when you need it.</p></div><button className="button primary add-button" onClick={()=>setOpen(true)}>＋ Add bookmark</button></header><SearchControls state={state} onChange={setState} onReset={reset} error={searchError}/><div className="stats"><strong>{items.length}</strong><span>{items.length===1?'matching link':'matching links'}</span></div><div aria-live="polite" className="sr-only">{message}</div>{loading?<p className="loading">Loading your bookmarks…</p>:noMatches?<section className="empty"><span aria-hidden="true">⌕</span><h2>No bookmarks found</h2><p>Try another expression or clear your filters.</p><button className="button secondary" onClick={reset}>Clear search</button></section>:<BookmarkList items={items}/>}<BookmarkForm open={open} onClose={()=>setOpen(false)} onSaved={bookmark=>{setItems(current=>[bookmark,...current]);setMessage('Bookmark saved.')}}/></main></ErrorBoundary>}

