payload.input:
const r = await tools.exec_command({cmd:"rg '^- \\[ \\] T' specs/001-bookmark-manager/tasks.md","workdir":"/work","yield_time_ms":10000,"max_output_tokens":30000});
const lines = r.output.trim().split("\n").filter(Boolean);
let patch = "*** Begin Patch\n*** Update File: /work/specs/001-bookmark-manager/tasks.md\n";
for (const line of lines) patch += `@@\n-${line}\n+${line.replace("- [ ]", "- [X]")}\n`;
patch += "*** End Patch";
text(`Marking ${lines.length} completed tasks`);
text(await tools.apply_patch(patch));

